/* Integer-only WDCNN inference for a Cortex-M4 (or any C99 target).
 *
 * Mirrors src/isense/int8.py operation for operation; tests/test_firmware.py
 * checks that the two produce bit-identical logits. Weights come from
 * wdcnn_weights.h, generated by scripts/run_firmware.py.
 *
 * Memory: two static int8 ping-pong buffers of WD_BUF bytes. No heap.
 */
#include <math.h>
#include <stdint.h>

#include "wdcnn.h"
#include "wdcnn_weights.h"

static int8_t buf_a[WD_BUF];
static int8_t buf_b[WD_BUF];

static int8_t requant(int32_t acc, float m)
{
    if (acc <= 0) {
        return 0; /* ReLU */
    }
    float v = floorf((float)acc * m + 0.5f);
    return v > 127.0f ? 127 : (int8_t)v;
}

static int conv1d(const int8_t *in, int cin, int lin, int8_t *out, int cout, int k, int stride,
                  const int8_t *w, const int32_t *b, const float *m)
{
    int lout = (lin - k) / stride + 1;
    for (int o = 0; o < cout; o++) {
        const int8_t *wo = w + o * cin * k;
        for (int t = 0; t < lout; t++) {
            int32_t acc = b[o];
            const int8_t *xt = in + t * stride;
            for (int c = 0; c < cin; c++) {
                const int8_t *xc = xt + c * lin;
                const int8_t *wc = wo + c * k;
                for (int j = 0; j < k; j++) {
                    acc += (int32_t)xc[j] * (int32_t)wc[j];
                }
            }
            out[o * lout + t] = requant(acc, m[o]);
        }
    }
    return lout;
}

static int maxpool2(const int8_t *in, int ch, int lin, int8_t *out)
{
    int lout = lin / 2;
    for (int c = 0; c < ch; c++) {
        for (int t = 0; t < lout; t++) {
            int8_t a = in[c * lin + 2 * t];
            int8_t b = in[c * lin + 2 * t + 1];
            out[c * lout + t] = a > b ? a : b;
        }
    }
    return lout;
}

int wdcnn_classify(const float *x, float *logits)
{
    for (int i = 0; i < WD_INPUT; i++) {
        float v = floorf(x[i] * WD_IN_SCALE + 0.5f);
        buf_a[i] = (int8_t)(v > 127.0f ? 127.0f : (v < -127.0f ? -127.0f : v));
    }
    int len = WD_INPUT;
    len = conv1d(buf_a, 1, len, buf_b, 16, 64, 8, wd_c0_w, wd_c0_b, wd_c0_m);
    len = maxpool2(buf_b, 16, len, buf_a);
    len = conv1d(buf_a, 16, len, buf_b, 32, 3, 1, wd_c1_w, wd_c1_b, wd_c1_m);
    len = maxpool2(buf_b, 32, len, buf_a);
    len = conv1d(buf_a, 32, len, buf_b, 64, 3, 1, wd_c2_w, wd_c2_b, wd_c2_m);
    len = maxpool2(buf_b, 64, len, buf_a);
    len = conv1d(buf_a, 64, len, buf_b, 64, 3, 1, wd_c3_w, wd_c3_b, wd_c3_m);

    int32_t pooled[64]; /* global average pool; the 1/len is folded into wd_head_m */
    for (int c = 0; c < 64; c++) {
        int32_t s = 0;
        for (int t = 0; t < len; t++) {
            s += buf_b[c * len + t];
        }
        pooled[c] = s;
    }
    int best = 0;
    for (int k = 0; k < WD_CLASSES; k++) {
        int32_t acc = 0;
        for (int c = 0; c < 64; c++) {
            acc += pooled[c] * (int32_t)wd_head_w[k * 64 + c];
        }
        float t = (float)acc * wd_head_m[k];
        logits[k] = t + wd_head_b[k];
        if (logits[k] > logits[best]) {
            best = k;
        }
    }
    return best;
}
